with lines as (select id, customer_id, coupon_codes, inline(items) from carts) select *, round(price / sum(price) over (partition by promo), 4) as price_share, sum(product_id) over (partition by customer_id) as customer_id_sum_product_id, round(qty / sum(qty) over (partition by customer_id, promo), 4) as qty_share, dense_rank() over (partition by promo, customer_id order by qty nulls last) as qty_dense_rank from lines
